package theme

import (
	"errors"
	"fmt"
	"io/fs"
	"log"

	"charm.land/lipgloss/v2"
)

// Background is what DevDesk knows about the terminal's background.
type Background int

const (
	// BackgroundUnknown: no detection has run.
	BackgroundUnknown Background = iota
	BackgroundDark
	BackgroundLight
	// BackgroundNoAnswer: the terminal did not answer in time.
	BackgroundNoAnswer
)

// autoName is the value of app.theme that asks for the terminal-based choice.
const autoName = "auto"

// minContrastText is the WCAG AA floor for normal text.
const minContrastText = 4.5

// Resolution is the outcome of picking a theme for app.theme.
type Resolution struct {
	Requested string // value written in app.theme ("auto" or a name)
	Name      string // theme actually applied
	Theme     *Theme
	Reason    string // why this theme, "" for a named theme
	Warning   string // footer Warn text, "" when none
}

// ResolveNamed loads the theme called name, falling back to the default theme
// with a warning when it cannot be used.
func ResolveNamed(name string) Resolution {
	r := Resolution{Requested: name}
	th, warn := loadOrWarn(name, false)
	r.Theme, r.Warning = th, warn
	r.Name = th.Name
	if warn == "" && (name == "" || name == "dark") {
		r.Name = "default"
	}
	return r
}

// ResolveAuto picks lightName on a light terminal and darkName otherwise.
// A candidate that cannot be loaded or whose text is unreadable on its own
// background gives the default theme and a warning.
func ResolveAuto(bg Background, darkName, lightName string) Resolution {
	r := Resolution{Requested: autoName}
	name := darkName
	switch bg {
	case BackgroundLight:
		name, r.Reason = lightName, "terminal is light"
	case BackgroundDark:
		r.Reason = "terminal is dark"
	case BackgroundNoAnswer:
		r.Reason = "no answer from the terminal"
	}
	r.Theme, r.Warning = loadOrWarn(name, true)
	r.Name = name
	if r.Warning != "" {
		r.Name = r.Theme.Name
	} else if name == "" || name == "dark" {
		r.Name = "default"
	}
	return r
}

// loadOrWarn loads name; on any failure it returns the default theme and the
// footer text explaining it. withContrast adds the readability check.
func loadOrWarn(name string, withContrast bool) (*Theme, string) {
	th, err := LoadTheme(name)
	if err != nil {
		log.Printf("WARN [theme] %v", err)
		if errors.Is(err, fs.ErrNotExist) {
			return DefaultTheme(), fmt.Sprintf("Theme %q not found — using default", name)
		}
		return DefaultTheme(), fmt.Sprintf("Theme %q is invalid — using default (see log)", name)
	}
	if withContrast {
		if err := MeetsMinimumContrast(th); err != nil {
			log.Printf("WARN [theme] theme %q: %v", name, err)
			return DefaultTheme(), fmt.Sprintf("Theme %q fails the contrast check — using default", name)
		}
	}
	return th, ""
}

// MeetsMinimumContrast checks that ColorText is readable on ColorBackground
// (at least 4.5:1, inclusive).
func MeetsMinimumContrast(t *Theme) error {
	ratio, err := ContrastRatio(lipgloss.Color(t.ColorText), lipgloss.Color(t.ColorBackground))
	if err != nil {
		return err
	}
	if ratio < minContrastText {
		return fmt.Errorf("text %s on background %s is %.2f:1, below %.1f:1", t.ColorText, t.ColorBackground, ratio, minContrastText)
	}
	return nil
}
package theme

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// isolateResolveHome points HOME at an empty dir and returns the user themes dir.
func isolateResolveHome(t *testing.T) string {
	t.Helper()
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("USERPROFILE", home)
	dir := filepath.Join(home, ".devdesk", "themes")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

func writeUserTheme(t *testing.T, dir, name, body string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(dir, name+".json"), []byte(body), 0o600); err != nil {
		t.Fatal(err)
	}
}

// userThemeJSON builds a complete theme file with the given text/background.
func userThemeJSON(name, text, bg string) string {
	return `{"name":"` + name + `","color_ok":"#00ff00","color_error":"#ff0000","color_warn":"#ff8800",` +
		`"color_primary":"#0000ff","color_secondary":"#0000cc","color_border":"#888888",` +
		`"color_text":"` + text + `","color_dim":"#999999","color_highlight":"#ffff00",` +
		`"color_white":"#ffffff","color_black":"#000000","color_background":"` + bg + `"}`
}

func TestResolveNamedDefaultHasNoWarning(t *testing.T) {
	isolateResolveHome(t)
	for _, name := range []string{"default", "dark", ""} {
		r := ResolveNamed(name)
		if r.Name != "default" || r.Theme == nil || r.Warning != "" {
			t.Errorf("ResolveNamed(%q) = %+v, want default without warning", name, r)
		}
		if r.Requested != name {
			t.Errorf("ResolveNamed(%q).Requested = %q", name, r.Requested)
		}
	}
}

func TestResolveNamedUnknownFallsBackWithWarning(t *testing.T) {
	isolateResolveHome(t)
	r := ResolveNamed("nope")
	if r.Name != "default" || r.Theme == nil || r.Theme.Name != "default" {
		t.Fatalf("ResolveNamed(nope) = %+v, want default theme", r)
	}
	if !strings.Contains(r.Warning, "nope") || !strings.Contains(r.Warning, "not found") {
		t.Errorf("Warning = %q, want it to name nope and say not found", r.Warning)
	}
}

func TestResolveNamedInvalidHexFallsBackWithWarning(t *testing.T) {
	dir := isolateResolveHome(t)
	writeUserTheme(t, dir, "broken", userThemeJSON("broken", "#zzzzzz", "#ffffff"))
	r := ResolveNamed("broken")
	if r.Name != "default" {
		t.Fatalf("Name = %q, want default", r.Name)
	}
	if !strings.Contains(r.Warning, "broken") || !strings.Contains(r.Warning, "is invalid") {
		t.Errorf("Warning = %q, want it to name broken and say is invalid", r.Warning)
	}
}

func TestResolveNamedShippedThemeNeedsNoUserFile(t *testing.T) {
	isolateResolveHome(t)
	r := ResolveNamed("github-light")
	if r.Name != "github-light" || r.Warning != "" {
		t.Errorf("ResolveNamed(github-light) = %+v, want it applied from the embedded copy", r)
	}
}

func TestResolveAutoLightPicksLightTheme(t *testing.T) {
	isolateResolveHome(t)
	r := ResolveAuto(BackgroundLight, "default", "github-light")
	if r.Name != "github-light" || r.Theme == nil || r.Reason != "terminal is light" || r.Warning != "" {
		t.Errorf("got %+v", r)
	}
	if r.Requested != "auto" {
		t.Errorf("Requested = %q, want auto", r.Requested)
	}
}

func TestResolveAutoDarkAndFallbacksPickDarkTheme(t *testing.T) {
	isolateResolveHome(t)
	cases := []struct {
		bg     Background
		reason string
	}{
		{BackgroundDark, "terminal is dark"},
		{BackgroundNoAnswer, "no answer from the terminal"},
		{BackgroundUnknown, ""},
	}
	for _, c := range cases {
		r := ResolveAuto(c.bg, "nord", "github-light")
		if r.Name != "nord" || r.Warning != "" {
			t.Errorf("bg %v: got %+v, want nord without warning", c.bg, r)
		}
		if c.reason != "" && r.Reason != c.reason {
			t.Errorf("bg %v: Reason = %q, want %q", c.bg, r.Reason, c.reason)
		}
	}
}

func TestResolveAutoUnknownCandidateFallsBackWithWarning(t *testing.T) {
	isolateResolveHome(t)
	r := ResolveAuto(BackgroundLight, "default", "nope")
	if r.Name != "default" || !strings.Contains(r.Warning, "nope") {
		t.Errorf("got %+v, want default + warning naming nope", r)
	}
	// The dark candidate is not consulted when the terminal is light.
	r = ResolveAuto(BackgroundLight, "nope", "github-light")
	if r.Name != "github-light" || r.Warning != "" {
		t.Errorf("got %+v, want github-light", r)
	}
}

func TestResolveAutoLowContrastCandidateFallsBackWithWarning(t *testing.T) {
	dir := isolateResolveHome(t)
	writeUserTheme(t, dir, "flat", userThemeJSON("flat", "#ffffff", "#ffffff"))
	r := ResolveAuto(BackgroundLight, "default", "flat")
	if r.Name != "default" {
		t.Fatalf("Name = %q, want default", r.Name)
	}
	if !strings.Contains(r.Warning, "flat") || !strings.Contains(r.Warning, "fails the contrast check") {
		t.Errorf("Warning = %q", r.Warning)
	}
}

func TestResolveAutoReadableUserThemeIsAccepted(t *testing.T) {
	dir := isolateResolveHome(t)
	writeUserTheme(t, dir, "paper", userThemeJSON("paper", "#000000", "#ffffff"))
	r := ResolveAuto(BackgroundLight, "default", "paper")
	if r.Name != "paper" || r.Warning != "" {
		t.Errorf("got %+v", r)
	}
}

func TestMinimumContrast(t *testing.T) {
	if err := MeetsMinimumContrast(DefaultTheme()); err != nil {
		t.Errorf("default theme: %v", err)
	}
	flat := DefaultTheme()
	flat.ColorText = flat.ColorBackground
	if err := MeetsMinimumContrast(flat); err == nil {
		t.Error("text equal to background must fail the 4.5:1 check")
	}
	// 4.5 is the floor: #767676 on white is 4.54:1, #777777 is 4.48:1.
	ok := DefaultTheme()
	ok.ColorText, ok.ColorBackground = "#767676", "#ffffff"
	if err := MeetsMinimumContrast(ok); err != nil {
		t.Errorf("4.54:1 must pass: %v", err)
	}
	ok.ColorText = "#777777"
	if err := MeetsMinimumContrast(ok); err == nil {
		t.Error("4.48:1 must fail")
	}
}

func TestEmbeddedThemesLoadWithoutUserDir(t *testing.T) {
	isolateResolveHome(t)
	th, err := LoadTheme("github-light")
	if err != nil || th.Name == "" {
		t.Fatalf("LoadTheme(github-light) with empty HOME: %v", err)
	}
	names, err := ListThemes()
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"default", "catppuccin-frappe", "catppuccin-latte", "catppuccin-macchiato",
		"catppuccin-mocha", "dark-plus", "github-dark", "github-light", "nord", "one-dark",
		"solarized-dark", "solarized-light", "tokyo-night"} {
		found := false
		for _, n := range names {
			if n == want {
				found = true
			}
		}
		if !found {
			t.Errorf("ListThemes() lacks %q: %v", want, names)
		}
	}
	if names[0] != "default" {
		t.Errorf("default must come first: %v", names)
	}
	seen := map[string]bool{}
	for _, n := range names {
		if seen[n] {
			t.Errorf("duplicate %q in %v", n, names)
		}
		seen[n] = true
	}
}

func TestUserThemeShadowsEmbeddedOne(t *testing.T) {
	dir := isolateResolveHome(t)
	writeUserTheme(t, dir, "github-light", userThemeJSON("my-override", "#000000", "#fefefe"))
	th, err := LoadTheme("github-light")
	if err != nil {
		t.Fatal(err)
	}
	if th.Name != "my-override" || th.ColorBackground != "#fefefe" {
		t.Errorf("got %q / %s, want the user's file to win", th.Name, th.ColorBackground)
	}
	names, _ := ListThemes()
	n := 0
	for _, name := range names {
		if name == "github-light" {
			n++
		}
	}
	if n != 1 {
		t.Errorf("github-light listed %d times, want 1", n)
	}
}

func TestListThemesIncludesUserOnlyTheme(t *testing.T) {
	dir := isolateResolveHome(t)
	writeUserTheme(t, dir, "mine", userThemeJSON("mine", "#000000", "#ffffff"))
	names, _ := ListThemes()
	found := false
	for _, n := range names {
		found = found || n == "mine"
	}
	if !found {
		t.Errorf("user theme missing from %v", names)
	}
}
package app

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/configuration"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// DEVDESK-201, H3: LoadTheme refuses a theme with an invalid hex, and the
// router keeps the current palette. No footer message is added (a follow-up if
// the user asks for one): the failure goes to the log only.
func TestASavedThemeWithAnInvalidHexKeepsTheCurrentPaletteAndPostsNoFooter(t *testing.T) {
	a := router(t, &fakeView{})
	t.Cleanup(func() {
		theme.ApplyTheme(theme.DefaultTheme())
		theme.CurrentThemeName = "default"
	})
	theme.ApplyTheme(theme.DefaultTheme())
	theme.CurrentThemeName = "default"

	dir, err := theme.ThemeDir()
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	bad := `{"name":"broken","color_ok":"#ggg","color_error":"#ff0000","color_warn":"#ff8800",` +
		`"color_primary":"#0000ff","color_secondary":"#8888ff","color_border":"#cccccc","color_text":"#000000",` +
		`"color_dim":"#888888","color_highlight":"#ffff00","color_white":"#ffffff","color_black":"#000000"}`
	if err := os.WriteFile(filepath.Join(dir, "broken.json"), []byte(bad), 0o644); err != nil {
		t.Fatal(err)
	}

	before := theme.Hex(theme.ColorPrimary)
	cfg := testConfig()
	cfg.App.Theme = "broken"
	_, cmd := a.Update(configuration.ConfigSavedMsg{Config: cfg, ThemeChanged: true})

	if got := theme.Hex(theme.ColorPrimary); got != before {
		t.Errorf("ColorPrimary = %s after a refused theme, want %s kept", got, before)
	}
	if theme.CurrentThemeName != "default" {
		t.Errorf("CurrentThemeName = %q, want %q kept", theme.CurrentThemeName, "default")
	}
	for _, m := range testutil.Msgs(cmd) {
		if p, ok := m.(components.PostFooterMsg); ok {
			t.Errorf("a refused theme posted a footer message: %+v", p)
		}
	}
}
